    /// Middleware для логирования медленных запросов.
    /// Отслеживает время выполнения каждого HTTP-запроса и записывает в лог,
    /// если оно превышает заданный порог (в миллисекундах).
    /// </summary>
    public class SlowRequestLoggingMiddleware
    {
        // Делегат, указывающий на следующий middleware в цепочке.
        private readonly RequestDelegate _next;

        // Инстанс ILogger для записи логов.
        private readonly ILogger<SlowRequestLoggingMiddleware> _logger;

        // Порог времени (в миллисекундах), превышение которого считается "медленным" запросом.
        private readonly int _slowThresholdMs;

        /// <summary>
        /// Инициализирует новый экземпляр класса <see cref="SlowRequestLoggingMiddleware"/>.
        /// </summary>
        /// <param name="next">Делегат следующего middleware в цепочке обработки запроса.</param>
        /// <param name="logger">Инстанс ILogger для записи логов.</param>
        /// <param name="slowThresholdMs">Порог времени в миллисекундах, при превышении которого запрос считается медленным.</param>
        public SlowRequestLoggingMiddleware(
            RequestDelegate next,
            ILogger<SlowRequestLoggingMiddleware> logger,
            int slowThresholdMs = 1000)
        {
            _next = next;
            _logger = logger;
            _slowThresholdMs = slowThresholdMs;
        }

        /// <summary>
        /// Обрабатывает входящий HTTP-запрос: измеряет время выполнения и логирует,
        /// если запрос оказался медленнее установленного порога.
