// Task представляет собой задачу, которую нужно выполнить.
type Task func() error

// PoolWorker — пул воркеров, обрабатывающий задачи из канала с ограничением параллелизма.
//
// Пул содержит фиксированное количество горутины-воркеров, которые берут задачи
// из внутреннего канала и выполняют их последовательно. Это позволяет контролировать
// уровень параллелизма: одновременно выполняется не более MaxWorkers задач.
type PoolWorker struct {
	// maxWorkers — максимальное количество одновременных воркеров.
	maxWorkers int

	// taskCh — канал для передачи задач в воркеры.
	taskCh chan Task

	// done — канал для сигнала завершения работы всех воркеров.
	done chan struct{}

	// wg — WaitGroup для ожидания завершения всех воркеров.
	wg sync.WaitGroup

	// ctx — контекст для управления жизненным циклом пула.
	ctx context.Context
}

// NewPoolWorker создаёт новый экземпляр пула воркеров.
//
// Параметры:
//   - maxWorkers: количество воркеров (параллельных горутины). Должно быть > 0.
//
// Возвращает указатель на созданный пул.
func NewPoolWorker(maxWorkers int) *PoolWorker {
	if maxWorkers <= 0 {
		maxWorkers = 1 // Защита от некорректного значения
	}

	p := &PoolWorker{
		maxWorkers: maxWorkers,
		taskCh:     make(chan Task),
		done:       make(chan struct{}),
		ctx:        context.Background(),
	}

	// Запускаем воркеров при создании
	p.startWorkers()

	return p
}

// startWorkers запускает все воркеры пула.
//
// Каждый воркер — это отдельная горутина, которая бесконечно читает задачи
// из канала taskCh и выполняет их. Воркеры завершают работу по сигналу
// из канала done или при отмене контекста.
func (p *PoolWorker) startWorkers() {
	for i := 0; i < p.maxWorkers; i++ {
		p.wg.Add(1)
		go p.worker(i)
	}
}

