import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.locks.ReentrantReadWriteLock;

/**
 * Кэш с вытеснением по давности использования (LRU - Least Recently Used)
 * и ограничением по памяти.
 *
 * <p>Реализация использует связный список для хранения элементов в порядке
 * их последнего использования, а хеш-таблицу для быстрого доступа к элементам.
 * Когда размер кэша превышает заданный лимит, самый старый элемент (тот,
 * который дольше всего не использовался) удаляется.</p>
 *
 * <p>Класс является потокобезопасным: все операции чтения и записи защищены
 * с помощью {@link ReentrantReadWriteLock}. Чтение может выполняться несколькими
 * потоками одновременно, но запись — только одним потоком.</p>
 *
 * @param <K> тип ключа
 * @param <V> тип значения
 */
public class LRUCache<K, V> {

    /**
     * Максимальное количество элементов, которое может храниться в кэше.
     * При превышении этого значения происходит вытеснение самого старого элемента.
     */
    private final int capacity;

    /**
     * Хеш-таблица для быстрого поиска элемента по ключу.
     * Ключ — это объект типа K, значение — ссылка на узел двусвязного списка.
     */
    private final Map<K, Node<K, V>> map;

    /**
     * Голова двусвязного списка. Указывает на самый недавно использованный элемент.
     */
    private Node<K, V> head;

    /**
     * Хвост двусвязного списка. Указывает на самый давно использованный элемент.
     */
    private Node<K, V> tail;

    /**
     * Текущее количество элементов в кэше.
     */
    private int size;

    /**
     * Блокировка для обеспечения потокобезопасности.
     * Используется ReadWriteLock: чтение может быть параллельным,
     * запись — только одной нитью.
     */
    private final ReentrantReadWriteLock lock = new ReentrantReadWriteLock();

    /**
     * Создаёт новый экземпляр LRU-кэша.
     *
     * @param capacity максимальная ёмкость кэша (должна быть положительной)
     * @throws IllegalArgumentException если capacity <= 0
     */
    public LRUCache(int capacity) {
        if (capacity <= 0) {
            throw new IllegalArgumentException("Ёмкость кэша должна быть положительной");
        }
        this.capacity = capacity;
        this.map = new HashMap<>();
        this.size = 0;
        // Инициализируем пустые указатели головы и хвоста
        this.head = null;
        this.tail = null;
    }

