/// Ошибка парсинга аргументов командной строки.
#[derive(Debug, Clone)]
pub enum ParseError {
    /// Неизвестный флаг или опция.
    UnknownFlag(String),
    /// Опция требует значение, но оно не было предоставлено.
    MissingValue(String),
    /// Дублирующийся флаг.
    DuplicateFlag(String),
    /// Невалидное значение для опции (например, неверный уровень сжатия).
    InvalidValue { option: String, value: String },
    /// Нет ни одного файла для обработки.
    NoFilesProvided,
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ParseError::UnknownFlag(flag) => write!(f, "Неизвестный флаг: {}", flag),
            ParseError::MissingValue(option) => write!(f, "Опция '{}' требует значение", option),
            ParseError::DuplicateFlag(flag) => write!(f, "Флаг '{}' указан более одного раза", flag),
            ParseError::InvalidValue { option, value } => {
                write!(f, "Невалидное значение '{}' для опции '{}'", value, option)
            }
            ParseError::NoFilesProvided => write!(f, "Не указаны файлы для обработки"),
        }
    }
}

