pub enum CompressionLevel {
    /// Минимальное сжатие (быстрее всего).
    Fastest,
    /// Баланс между скоростью и степенью сжатия.
    Balanced,
    /// Максимальное сжатие (медленнее всего).
    Slowest,
}

impl From<u8> for CompressionLevel {
    fn from(value: u8) -> Self {
        match value {
            0..=3 => CompressionLevel::Fastest,
            4..=6 => CompressionLevel::Balanced,
            7..=9 => CompressionLevel::Slowest,
            _ => CompressionLevel::Balanced, // по умолчанию — баланс
        }
    }
}

impl Default for CompressionLevel {
    fn default() -> Self {
        CompressionLevel::Balanced
    }
}

