// Метод Get возвращает значение из кэша по указанному ключу.
// Возвращает строку со значением и булево значение, указывающее,
// найдено ли значение в кэше и не истекло ли время его жизни (TTL).
func (c *Cache) Get(key string) (string, bool) {
    // Блокируем чтение данных с помощью read-lock.
    // Это позволяет нескольким горутинам одновременно читать данные,
    // но запрещает запись во время чтения.
    c.mu.RLock()

    // Пытаемся получить элемент из карты items по заданному ключу.
    // ok будет true, если ключ найден, иначе false.
    e, ok := c.items[key]

    // Разблокируем чтение, так как доступ к данным завершён.
    c.mu.RUnlock()

    // Проверяем, был ли элемент найден (ok == true)
    // и не истекло ли время его жизни (текущее время раньше времени истечения).
    // Если элемент не найден или срок действия истёк — возвращаем пустую строку и false.
    if !ok || time.Now().After(e.expires) {
        return "", false
    }

    // Если элемент найден и ещё действует — возвращаем его значение и true.
    return e.value, true
}
