/**
 * Функция для повторного выполнения блока кода при возникновении IOException.
 *
 * @param times Количество попыток выполнения блока.
 * @param block Лямбда-функция, содержащая код, который нужно выполнить.
 * @return Результат выполнения блока, если он завершился успешно.
 * @throws IOException Если все попытки завершились исключением IOException.
 * @throws IllegalStateException Если количество попыт (times) меньше или равно 0.
 */
fun <T> retry(times: Int, block: () -> T): T {
    // Переменная для хранения последнего возникшего исключения IOException
    var last: Throwable? = null

    // Цикл, выполняющий блок `block` не более `times` раз
    repeat(times) {
        try {
            // Пытаемся выполнить блок и вернуть его результат
            return block()
        } catch (e: IOException) {
            // Если произошло исключение IOException, сохраняем его в переменную `last`
            // и продолжаем цикл (следующая итерация)
            last = e
        }
    }

    // Если все попытки завершились исключением, бросаем последнее сохраненное исключение.
    // Если исключений не было (что возможно только при times <= 0), бросаем IllegalStateException
    throw last ?: IllegalStateException("times must be > 0")
}
```

