// Get возвращает значение из кэша по указанному ключу, если оно существует и не истекло время жизни (TTL).
//
// Функция выполняет чтение из кэша с использованием блокировки чтения (RLock), что позволяет
// нескольким горутинам одновременно читать данные без взаимной блокировки.
//
// Параметры:
//   - key — строковый ключ, по которому выполняется поиск в кэше.
//
// Возвращаемые значения:
//   - string — значение, связанное с ключом, если оно найдено и не устарело; пустая строка, если значение отсутствует или устарело.
//   - bool — true, если значение успешно получено и актуально; false, если ключ не найден или время жизни элемента истекло.
//
// Граничные случаи:
//   - Если ключ не существует в кэше, функция вернет ("", false).
//   - Если элемент существует, но его время жизни (expires) уже прошло, функция также вернет ("", false).
//   - Функция не изменяет состояние кэша и не удаляет устаревшие элементы — очистка происходит только при явном вызове методов очистки или при добавлении новых элементов (в зависимости от реализации).
//
// Примечание:
//   - Функция является потокобезопасной благодаря использованию RWMutex.
//   - Не рекомендуется использовать эту функцию для хранения критически важных данных без дополнительной проверки на стороне приложения, так как кэш может быть очищен или перезаписан другими компонентами системы.
func (c *Cache) Get(key string) (string, bool) {
	c.mu.RLock()
	e, ok := c.items[key]
	c.mu.RUnlock()
	if !ok || time.Now().After(e.expires) {
		return "", false
	}
	return e.value, true
}
