/// * Вектор из одного элемента: возвращается этот единственный элемент.
/// * Вектор содержит `NaN`: поведение не определено, так как `partial_cmp` для `NaN` возвращает `None`,
///   и вызов `.unwrap()` приведет к панике. Рекомендуется проверять наличие `NaN` перед вызовом функции.
/// * Вектор содержит `+inf` или `-inf`: такие значения корректно обрабатываются при сравнении,
///   но могут привести к непредсказуемым результатам при вычислении среднего (например, `(+inf + -inf) / 2.0 = NaN`).
///
/// # Примеры
/// ```
/// let mut v = vec![3.0, 1.0, 2.0];
/// assert_eq!(median(&mut v), Some(2.0));
/// // После вызова v == [1.0, 2.0, 3.0]
///
/// let mut v = vec![4.0, 1.0, 3.0, 2.0];
/// assert_eq!(median(&mut v), Some(2.5));
/// // После вызова v == [1.0, 2.0, 3.0, 4.0]
///
/// let mut v = vec![];
/// assert_eq!(median(&mut v), None);
/// ```
pub fn median(v: &mut Vec<f64>) -> Option<f64> {
    if v.is_empty() { return None; }
    v.sort_by(|a, b| a.partial_cmp(b).unwrap());
    let m = v.len() / 2;
    Some(if v.len() % 2 == 0 { (v[m - 1] + v[m]) / 2.0 } else { v[m] })
}
```

